import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
};

export default nextConfig;

export type AgentCard = {
  agent_id: string;
  name: string;
  role: string;
  repo_path: string | null;
  tool: string;
  last_seen: string | null;
  current_task: string | null;
};

export type TaskCard = {
  id: string;
  title: string;
  status: string;
  assigned_agent: string | null;
  locks: string[];
  prompt: string | null;
};

export type ApprovalCard = {
  id: string;
  task_id: string;
  agent_id: string | null;
  action_class: string;
  summary: string;
  justification: string;
  blast_radius: string;
  alternative: string;
  diff_stat: string;
  status: string;
};

export type TapeEvent = {
  id: number;
  created_at: string;
  agent_id: string | null;
  task_id: string | null;
  kind: string;
  message: string;
};

export type PolicyState = {
  preset: string;
  modes: Record<string, string>;
};

export type Board = {
  agents: AgentCard[];
  tasks: TaskCard[];
  pending_approvals: ApprovalCard[];
  events: TapeEvent[];
  policy: PolicyState;
  model_offline: boolean;
  ntfy_enabled: boolean;
};

export function hubBase(): string {
  if (typeof window === "undefined") {
    return process.env.NEXT_PUBLIC_HUB_URL || "http://127.0.0.1:8787";
  }
  if (process.env.NEXT_PUBLIC_HUB_URL) return process.env.NEXT_PUBLIC_HUB_URL;
  return `http://${window.location.hostname}:8787`;
}

export async function hub(path: string, init?: RequestInit): Promise<Response> {
  const headers = new Headers(init?.headers);
  if (init?.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
  const response = await fetch(`${hubBase()}${path}`, {
    ...init,
    headers,
    credentials: "include",
  });
  if (response.status === 401 && !path.startsWith("/api/session")) {
    window.location.assign("/login");
  }
  return response;
}

