"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

const LINKS = [
  ["/", "Board"],
  ["/tape", "Tape"],
  ["/gate", "Gate"],
  ["/steer", "Steer"],
  ["/settings", "Levels"],
];

export function Shell({ children }: { children: React.ReactNode }) {
  const path = usePathname();
  if (path === "/login") return <>{children}</>;
  return (
    <div className="desk">
      {children}
      <nav className="nav" aria-label="Dispatch">
        {LINKS.map(([href, label]) => (
          <Link key={href} href={href} aria-current={path === href ? "page" : undefined}>
            {label}
          </Link>
        ))}
      </nav>
    </div>
  );
}

"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";
import { hub } from "../../hub/client";

export default function LoginPage() {
  const router = useRouter();
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");

  async function onSubmit(event: FormEvent) {
    event.preventDefault();
    setError("");
    const response = await hub("/api/session", {
      method: "POST",
      body: JSON.stringify({ pin }),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      setError(body.detail || "The hub refused that PIN.");
      return;
    }
    router.push("/");
  }

  return (
    <main className="login">
      <form className="card stack" onSubmit={onSubmit}>
        <p className="eyebrow">Field radio</p>
        <h1>Dispatch</h1>
        <p className="quiet">The agents keep working on the desk machine. This PIN opens the board.</p>
        <label className="field">
          PIN
          <input
            inputMode="numeric"
            autoComplete="current-password"
            value={pin}
            onChange={(event) => setPin(event.target.value)}
            required
            minLength={4}
          />
        </label>
        {error ? <p className="error">{error}</p> : null}
        <button className="wide" type="submit">Open the board</button>
      </form>
    </main>
  );
}

"use client";

