  const [prompt, setPrompt] = useState("");
  const [agentId, setAgentId] = useState("agent-ui");

  async function load() {
    const response = await hub("/api/board");
    if (!response.ok) return;
    const next = (await response.json()) as Board;
    setBoard(next);
  }

  useEffect(() => {
    void load();
    const timer = window.setInterval(() => void load(), 2000);
    return () => window.clearInterval(timer);
  }, []);

  async function assign(event: FormEvent) {
    event.preventDefault();
    setError("");
    const response = await hub("/api/tasks", {
      method: "POST",
      body: JSON.stringify({ title, prompt, agent_id: agentId, files: [] }),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      setError(body.detail || "The task was not queued.");
      return;
    }
    setTitle("");
    setPrompt("");
    await load();
  }

  const holds = board?.pending_approvals.length ?? 0;

  return (
    <main className="stack">
      <header className="mast">
        <div>
          <p className="eyebrow">Night shift</p>
          <h1>Board</h1>
        </div>
        <span className={holds ? "pill hold" : "pill"}>{holds} hold</span>
      </header>
      {board?.model_offline ? (
        <p className="banner">Model offline. Edits inside the lock are local dry-runs until a key or Ollama is set.</p>
      ) : null}
      <section className="stack" aria-label="Agents">
        {(board?.agents ?? []).map((agent) => (
          <article className="card agent" key={agent.agent_id}>
            <div>
              <strong>{agent.name}</strong>
              <div className="meta">{agent.role}</div>
              <div className="quiet">{agent.repo_path || "No project folder yet"}</div>
            </div>
            <span className="pill">{agent.tool || "idle"}</span>
          </article>
        ))}
      </section>
      <form className="card stack" onSubmit={assign}>
        <h2>Send a task</h2>
        <label className="field">
          Title
          <input value={title} onChange={(event) => setTitle(event.target.value)} required />
        </label>
        <label className="field">
          What should change
          <textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} required />
        </label>
        <label className="field">
          Agent
          <select value={agentId} onChange={(event) => setAgentId(event.target.value)}>
            {(board?.agents ?? []).map((agent) => (
              <option key={agent.agent_id} value={agent.agent_id}>
                {agent.name}
              </option>
            ))}
          </select>
        </label>
        {error ? <p className="error">{error}</p> : null}
        <button className="wide" type="submit">Queue it</button>
      </form>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import { hub, hubBase } from "../../hub/client";
import type { TapeEvent } from "../../hub/types";

export default function TapePage() {
  const [events, setEvents] = useState<TapeEvent[]>([]);

  useEffect(() => {
    let after = 0;
    let source: EventSource | null = null;
    let poll = 0;
    const seen = new Set<number>();

    function push(rows: TapeEvent[]) {
      const fresh = rows.filter((row) => !seen.has(row.id));
      fresh.forEach((row) => seen.add(row.id));
      if (!fresh.length) return;
      after = fresh[fresh.length - 1].id;
      setEvents((current) => [...current, ...fresh].slice(-80));
    }

    async function pull() {
      const response = await hub(`/api/events/recent?after=${after}`);
      if (!response.ok) return;
      const body = (await response.json()) as { events: TapeEvent[] };
      push(body.events);
    }

    void pull();
    try {
      source = new EventSource(`${hubBase()}/api/events?after=0`, { withCredentials: true });
      source.onmessage = (message) => {
        push([JSON.parse(message.data) as TapeEvent]);
      };
      source.onerror = () => {
        source?.close();
        poll = window.setInterval(() => void pull(), 2000);
      };
    } catch {
      poll = window.setInterval(() => void pull(), 2000);
    }
    const backup = window.setInterval(() => void pull(), 4000);
    return () => {
      source?.close();
      window.clearInterval(poll);
      window.clearInterval(backup);
    };
  }, []);

  return (
    <main>
      <p className="eyebrow">Live</p>
      <h1>Tape</h1>
      <div className="tape" style={{ marginTop: 16 }}>
        {events.length === 0 ? <p className="quiet">Waiting for the first line from the desk.</p> : null}
        {events.map((event) => (
          <article className={`line ${event.kind}`} key={event.id}>
            <div className="kind">{event.kind}</div>
            <div>{event.message}</div>
          </article>
        ))}
      </div>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import { hub } from "../../hub/client";
import type { ApprovalCard } from "../../hub/types";

export default function GatePage() {
  const [gates, setGates] = useState<ApprovalCard[]>([]);
  const [note, setNote] = useState("");
  const [error, setError] = useState("");

  async function load() {
    const response = await hub("/api/approvals");
    if (!response.ok) return;
    const body = (await response.json()) as { approvals: ApprovalCard[] };
    setGates(body.approvals);
  }

  useEffect(() => {
    void load();
    const timer = window.setInterval(() => void load(), 1500);
    return () => window.clearInterval(timer);
  }, []);

  async function decide(decision: "proceed" | "revise" | "stop") {
    const gate = gates[0];
    if (!gate) return;
    setError("");
    const response = await hub("/api/approvals", {
      method: "POST",
      body: JSON.stringify({ id: gate.id, decision, note }),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      setError(body.detail || "The gate did not move.");
      return;
    }
    setNote("");
    await load();
  }

  const gate = gates[0];

  return (
    <main className="stack">
      <p className="eyebrow">Consequential</p>
      <h1>Gate</h1>
      {!gate ? <p className="quiet">Clear board. Routine work is running without you.</p> : null}
      {gate ? (
        <article className="ticket">
          <div className="band">HOLD</div>
          <p className="eyebrow" style={{ color: "var(--hold)" }}>{gate.action_class}</p>
          <h2>{gate.summary}</h2>
          <p>{gate.justification}</p>
          <p><strong>Blast.</strong> {gate.blast_radius}</p>
          {gate.diff_stat ? <pre className="diff">{gate.diff_stat}</pre> : null}
          <p><strong>If you refuse.</strong> {gate.alternative}</p>
          {gate.action_class === "git_push" ? <p>Push stays at the desk.</p> : null}
          <label className="field">
            Revise note
            <textarea value={note} onChange={(event) => setNote(event.target.value)} />
          </label>
          {error ? <p className="error">{error}</p> : null}
          <div className="actions">
            <button type="button" onClick={() => void decide("proceed")}>Proceed</button>
            <button className="ghost" type="button" onClick={() => void decide("revise")}>Revise</button>
            <button className="stop" type="button" onClick={() => void decide("stop")}>Stop</button>
          </div>
        </article>
      ) : null}
    </main>
  );
}

