def pin_locked() -> bool:
    conn = connect()
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM pin_attempts WHERE created_at >= ?",
        (_attempt_cutoff(),),
    ).fetchone()
    conn.close()
    return int(row["n"]) >= 8


