def repo_allowed(folder: Path) -> bool:
    raw = os.getenv("HACKSWARM_REPO_ROOTS", "").strip()
    if not raw:
        return True
    resolved = folder.resolve()
    for part in raw.split(";"):
        root = Path(part.strip()).expanduser()
        if not part.strip():
            continue
        root = root.resolve()
        if resolved == root or resolved.is_relative_to(root):
            return True
    return False

