    python = _aider_python()
    if python[0] != sys.executable:
        try:
            probe = subprocess.run(
                [*python, "-c", "import aider"],
                capture_output=True,
                timeout=30,
                check=False,
            )
            return probe.returncode == 0
        except (OSError, subprocess.TimeoutExpired):
